// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit, address nonOwner) public {
        vm.assume(nonOwner != address(this));

        uint256 oldBetLimit = c.currentBetLimit();
        vm.prank(nonOwner);
        try c.AdjustBetAmounts(newBetLimit) { } catch { }
        uint256 newBetLimitAfter = c.currentBetLimit();

        assertTrue(newBetLimitAfter == oldBetLimit);
    }
}
